name: Test, Build, and Deploy
on: [push, pull_request]
jobs:
  test: { /* Module 21's test suite, run automatically on every push */ }
  build: { needs: test /* Module 25's automated build stage */ }
  deploy: { needs: build /* Module 25's automated deploy stage */ }
// Every single step here replaces what would otherwise be a manual,
// error-prone, repeatedly-performed human action

// PRINCIPLE 3 (Measure everything, continuously) - Module 25 lesson 4:
app.get('/health', async (req, res) => {
  const checks = { database: await checkDb(), cache: await checkCache() };
  // continuously, automatically verified, never a one-time, manual check
});

// PRINCIPLE 4 (Treat infrastructure as code) - Module 25 lesson 2:
// FROM node:20-alpine AS builder
// ... (the ENTIRE Dockerfile, version-controlled exactly like any
